# aeneid-059 (VIII.219-305): t is cut from the edition by A.cut; l, i, n drafted from the Latin.
import sys, os
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE); sys.path.insert(0, os.path.join(HERE, '..', '..'))
import aeneid_lib as A

TITLE = 'Hercules et Cacus. Ara Maxima'
PART = "Hercules and Cacus (VIII.219–305)"
TITLE_EN = "Hercules and Cacus — Aeneid VIII.219–305"
ABOUT = ("Evander goes on with the story he began at the feast. When the stolen heifer lowed from inside the cave, Hercules "
"flared up in fury, seized his knotted club and ran up the Aventine. Cacus, terrified for the first time, fled into his den and "
"dropped the great hanging stone across the entrance; Hercules raged three times round the hill, then wrenched off the crag that "
"roofed the cave and sent it crashing into the river, so that daylight poured into the monster's lair like light breaking into "
"the underworld. Cacus, cornered, filled the cave with smoke and fire; Hercules leapt down through the flames, caught him in a "
"wrestler's grip and throttled him, and the stolen cattle and the shapeless corpse were dragged out into the sun. That, says "
"Evander, is why the rite is kept, by the families of the Potitii and the Pinarii, at the altar that is and always will be called "
"the Greatest, the Ara Maxima; and he bids the Trojans wreathe their heads and pour wine to a god they share. As evening falls the "
"priests return, the feast begins again, and the Salii, a chorus of young men and a chorus of old, sing a hymn to Hercules: the "
"snakes he strangled in his cradle, the cities he sacked, his labours under Eurystheus, the monsters he overcame, and last of all "
"Cacus himself, while the woods and hills ring with the sound.")

U = [
(220, 'dolor:',
 "Here indeed Alcides's with frenzies had blazed up, with black\nbile, resentment:",
 "At this the resentment of Alcides blazed up in fury, with black bile:",
 """A new paragraph in Greenough. Evander is still speaking: his speech, begun at 8.185, runs on until 275, so no new speech mark opens here. 'Hic', 'at this point', when the heifer lowed (8.217–218). 'Alcidae', dative of reference with 'dolor', 'to Alcides', i.e. 'Alcides' resentment'; 'Alcides' is Hercules, as at 8.203. 'furiis', ablative, 'with frenzies'. 'exarserat', pluperfect, 'had blazed up': it was alight in an instant, before anything else is told. 'atro felle', 'with black bile', split across the line: ancient medicine put the seat of anger in the gall (L&S under 'fel'). 'dolor' is resentment at a wrong, not bodily pain. Elision 'ver(o) Alcidae'."""),
(221, 'montis.',
 "he seizes weapons in his hand, and with knots weighted\nthe oak, and at a run makes for the steep heights of the airy mountain.",
 "he snatches up his weapons and his club of oak, heavy with knots, and runs to the steep heights of the soaring mountain.",
 """'rapit', historic present, as through most of this narrative. 'arma' are his weapons in general, then one in particular: 'nodis… gravatum robur', 'oak weighted with knots', the club that is Hercules's emblem, the noun held over to the next line. 'robur' is first hard oak-wood, then anything made of it. 'aerii… montis', 'of the airy mountain', framing the line: the Aventine, named at 231. 'aerius' (from 'aer') means reaching up into the air, lofty. 'cursu', 'at a run', ablative of manner. 'ardua', neuter plural used as a noun, 'the steep places', 'the heights'."""),
(223, 'oculis:',
 "Then for the first time our people saw Cacus afraid\nand troubled in his eyes:",
 "Then for the first time our people saw Cacus afraid, with terror in his eyes:",
 """'nostri', nominative plural, 'our people', the Arcadians: Evander was an eyewitness, as he implied at 8.190 ('Iam primum… aspice'). 'videre' = 'viderunt', the '-ere' perfect again. 'timentem turbatumque', participles predicative with 'Cacum', 'saw Cacus fearing and troubled'. 'oculis', ablative of respect, 'in his eyes': the fear shows in his look. 'primum', 'for the first time': the monster who had terrorised the valley had never before been seen to be afraid. Elision 'turbatumqu(e) oculis'."""),
(224, 'alas.',
 "he flees at once, swifter than the East Wind,\nand makes for the cave; to his feet fear added wings.",
 "at once he takes to flight, swifter than the east wind, and makes for his cave; fear put wings on his feet.",
 """'ilicet', 'at once', 'straightway', in origin 'ire licet', 'you may go', the formula that dismissed an assembly. 'ocior Euro', 'swifter than Eurus', ablative of comparison; 'ocior' is a comparative with no positive in use. 'Euro': Greek 'eu' is one syllable, 'Eu-ro', two syllables in all. 'speluncamque petit', the cave described at 8.193–197. 'pedibus timor addidit alas', 'fear added wings to his feet', a proverbial turn ('pedibus', dative with the compound 'addidit'); the clause stands with no connective (asyndeton), as a vivid comment."""),
(227, 'postis,',
 "When himself he had shut in, and, the chains broken, the huge\nhe had let fall rock, which by iron and the skill of his father\nhung, and propped he had fortified with the barrier the doorposts,",
 "As soon as he had shut himself in, breaking the chains and letting fall the huge rock that hung there by iron and his father's craft, and had made the propped doorposts fast with this barrier,",
 """'Ut', 'when', 'as soon as', with perfect indicatives ('inclusit… deiecit… emuniit'), as at 8.107. 'ruptis… catenis', ablative absolute, 'the chains broken'. 'immane… saxum', 'the huge rock', framing the clause across the line: a stone slung over the entrance like a portcullis, held by iron chains. 'ferro… et arte paterna', 'by iron and his father's art': Cacus's father is Vulcan, the smith-god (8.198). 'pendebat', imperfect, 'had hung' there till now. 'fultos… postis', 'the propped doorposts', accusative plural in '-is'; 'emuniit', 'fortified' (e- + munio), with 'obice', 'with the barrier', the fallen stone itself. Elisions 'ses(e) inclusit', 'ruptisqu(e) immane', 'fultosqu(e) emuniit'."""),
(230, 'infrendens.',
 "lo, raging in his spirit, was at hand the Tirynthian, and every\napproach surveying, this way his face he turned and that,\nwith his teeth gnashing.",
 "see, the Tirynthian was there, raging at heart, surveying every approach, turning his gaze this way and that, and grinding his teeth.",
 """'ecce', 'look!', bringing the scene before our eyes. 'furens animis', 'raging in his spirit', 'animis' a plural of intensity. 'aderat', 'was there', the pluperfect sense of speed again. 'Tirynthius', 'the man of Tiryns', the city in the Argolid where Hercules grew up. Line 228 is hypermetric: it has one syllable too many, and the '-que' of 'omnemque' is elided into the vowel that begins 229, 'accessum' (the lines are read as continuous, synapheia). Virgil uses this sparingly; here it lets the line spill over like the hero's rage. 'omnem… accessum', 'every approach'. 'huc… et illuc', 'hither and thither'. 'ora ferebat', 'kept turning his face'. 'dentibus infrendens', 'gnashing with his teeth'."""),
(232, 'resedit.',
 "Three times, the whole, burning with anger,\nhe surveys of the Aventine the hill, three times the stony he tries\nthreshold in vain, three times weary in the valley he sat down.",
 "Three times, hot with anger, he went over the whole of the Aventine hill; three times he tried the stone doorway in vain; three times he sat down, worn out, in the valley.",
 """'Ter… ter… ter', 'three times', a tricolon with anaphora, each limb a little more hopeless; the threefold attempt is epic habit (Achilles thrice lunges at Hector, whom Apollo has hidden in mist, Iliad 20, from memory, and Aeneas thrice tries to embrace Creusa's shade, 2.792). 'totum… Aventini montem', 'the whole hill of the Aventine', named now in Evander's story: the southernmost of Rome's hills, across the valley from the Palatine. 'fervidus ira', 'burning with anger'. 'lustrat', 'goes round', surveys. 'saxea… limina', 'the stone threshold', the doorway blocked by the rock. 'nequiquam', 'in vain'. 'resedit', perfect, 'sat down': the present tenses give way to the past at the end of the effort. 'valle', ablative of place."""),
(235, 'volucrum.',
 "There stood a sharp flint, with cut away on all sides rocks,\nfrom the cave's back rising, very high to the sight,\nfor the nests of ill-omened a home convenient birds.",
 "There was a pointed crag of flint, sheer on every side, rising from the ridge above the cave, towering to look at, a fit home for the nests of birds of evil omen.",
 """'Stabat', 'there stood', placed first, the usual opening of a description of place in epic ('Est locus…'). 'acuta silex', 'a sharp flint', a pinnacle of hard rock; 'silex' is usually masculine, here feminine, as poets sometimes make it (L&S). 'praecisis undique saxis', ablative absolute or of description, 'its rocks cut sheer on all sides'. 'speluncae dorso', 'on the back of the cave', the ridge above it; 'insurgens', 'rising up'. 'altissima visu', 'very high to see', 'visu' the supine in '-u', an ablative of respect. 'dirarum… volucrum', 'of ill-omened birds', vultures or owls, framing the line, with 'nidis' dative after 'opportuna', 'convenient for nests'. Elision 'dors(o) insurgens'."""),
(238, 'radicibus;',
 "This, as sloping from the ridge onto the left it leaned river,\non the right against it straining he shook, and from its lowest\ntorn away loosed roots;",
 "Where it leaned forward from the ridge over the river on the left, he braced himself against it from the right and shook it, and wrenched it loose, torn from its deepest roots;",
 """'Hanc', the crag, object of 'concussit' and 'solvit'. 'ut', 'as', 'where', describing how it stood: 'prona iugo', 'sloping forward from the ridge', 'incumbebat in amnem', 'leaned towards the river', the Tiber, on the left as Hercules faces it. The Latin Library has 'ad amnem', with no change of sense. 'dexter', 'on the right', an adjective doing an adverb's work, as Latin often prefers. 'in adversum nitens', 'straining against it', pushing from the opposite side. 'imis… radicibus', ablative of separation, 'from its lowest roots', framing 'avolsam solvit'. 'avolsam', Greenough's spelling of 'avulsam' (o for u after v, as in 'volnus'), 'torn away', from 'avello'. Elision 'laev(um) incumbebat'."""),
(240, 'amnis.',
 "then suddenly\nhe pushed it, at which shove the vast thunders sky,\nleap apart the banks and flows back terrified the river.",
 "then all at once he heaved it over; at the shock the whole vast sky thundered, the banks sprang apart, and the river ran backwards in terror.",
 """'inde repente', 'then suddenly'. 'inpulit', Greenough's spelling of 'impulit', the prefix 'in-' unassimilated; so too 'inpulsu' for 'impulsu': the repetition, verb then noun, makes the shove echo. 'inpulsu quo', 'at which shock', the relative placed second ('quo inpulsu'), ablative of cause. 'maximus… aether', 'the vast sky', framing. Greenough prints no comma after 'aether', so the relative can be read with all three verbs ('at which the sky thunders, the banks leap apart, the river flows back'); most texts punctuate there and start a new clause. The sense is the same. 'dissultant', 'leap apart', a rare compound of 'salto'. 'refluit', 'flows back'. 'exterritus', 'terrified', the river given feeling. Elision 'refluitqu(e) exterritus'."""),
(242, 'cavernae:',
 "But the cave and Cacus's, uncovered, appeared the huge\npalace, and shadowy deep within lay open the caverns:",
 "And now the cave was laid bare, and the huge palace of Cacus came into view, and its dark caverns lay open far within:",
 """'At' marks the turn from the crash to what it reveals. 'specus', 'cave', a fourth-declension noun, here masculine. 'Caci… ingens regia', 'the huge palace of Cacus', a grim irony for a robber's den, framing 'detecta apparuit', 'appeared uncovered', since the roof of rock is gone. The singular verb 'apparuit' agrees with the nearer subject. 'umbrosae… cavernae', 'shadowy caverns', framing the second clause. 'penitus', 'deep within'. 'patuere' = 'patuerunt', 'lay open'. Elisions 'detect(a) apparuit', 'regi(a) et'."""),
(246, 'manes.',
 "not otherwise than if somehow, deep within, by force the earth gaping\nthe infernal should unbar seats and the realms disclose,\npale ones, hateful to the gods, and from above the huge pit\nbe seen, should tremble at the let-in light the shades.",
 "just as if some force should split the earth open to its depths and unlock the dwellings of the underworld and lay bare the pale kingdoms the gods abhor, and the vast abyss could be seen from above, and the shades of the dead cower as the light streamed in.",
 """A simile. 'non secus ac si', 'not otherwise than if'; 'siqua' (= 'si qua'), 'if in any way', 'qua' an adverb. 'vi', 'by some force', as of an earthquake. 'reseret… recludat… cernatur… trepident', present subjunctives of an imagined case. 'infernas… sedes', 'the dwellings below'. 'regna… pallida', 'the pale realms', the colour of the bloodless dead; 'dis invisa', 'hated by the gods'. The model is Iliad 20, where Hades leaps from his throne in fear that Poseidon will split the earth and show his dread, mouldering halls, which even the gods abhor, to mortals and immortals (from memory). 'barathrum', a Greek word, 'pit', 'abyss'. 'inmisso lumine', ablative absolute, 'the light let in' ('inmisso' for 'immisso'). 'manes', 'the shades'. Elision 'superqu(e) immane'."""),
(250, 'instat.',
 "So, by unhoped-for caught light suddenly,\nand shut in in the hollow rock, and unwonted roaring,\nfrom above Alcides with missiles presses, and all weapons\nsummons, and with branches and huge millstones presses on.",
 "So, caught suddenly by the light he never looked for, shut in the hollow rock and bellowing as he had never bellowed, Cacus was assailed from above by Alcides with missiles; the hero called every weapon to his aid and pressed him hard with branches and boulders as big as millstones.",
 """'Ergo', 'so then', back to the story after the simile. 'deprensum… inclusumque… rudentem', three participles describing Cacus, the object of 'premit', who is not named: 'him, caught… shut in… roaring'. 'insperata… luce', 'by the unhoped-for light', framing the line with 'deprensum… repente' between. 'cavo saxo', ablative of place. 'insueta rudentem', 'roaring unaccustomed things', a neuter plural accusative used like an adverb, 'roaring as never before'. 'desuper', 'from above', standing over the unroofed cave. 'omniaque arma advocat', 'and calls all weapons to his aid', anything that will serve. 'molaribus', from 'molaris', 'a millstone', then a rock of millstone size. 'instat', 'presses on'. Elisions 'Erg(o) insperata', 'sax(o) atque', 'atqu(e) insueta', 'omniaqu(e) arma'."""),
(253, 'caeca,',
 "He however, for not now escape was remaining any from danger,\nfrom his jaws huge smoke (wonderful to say)\nspews out, and wraps the house in darkness, blind,",
 "But Cacus, since there was now no escape left from his peril, belched from his throat a huge cloud of smoke, marvellous to tell, and wrapped the dwelling in blinding darkness,",
 """'Ille autem', 'but he', Cacus. 'neque enim… ulla', a parenthesis giving the reason, 'for there was no longer any escape from the danger'; 'super' is the adverb 'over', 'left', standing for 'superest' (or 'supererat'), with the verb left out. 'pericli' = 'periculi', the shorter form, as at 8.188, an objective genitive with 'fuga', 'flight from danger'. 'faucibus', 'from his jaws', ablative of separation. 'mirabile dictu', 'wonderful to say', the supine in '-u' again, a set phrase. 'evomit', 'vomits forth', the fire-breathing son of Vulcan (8.198–199). 'caligine caeca', 'with blind darkness', darkness that makes others blind. Elisions 'Ill(e) autem', 'nequ(e) enim'."""),
(255, 'tenebris.',
 "the view snatching from eyes, and he masses under the cave\nsmoke-bearing night, with fire mingled darkness.",
 "robbing the eyes of sight, and rolled up beneath the rock a night full of smoke, darkness shot through with fire.",
 """'prospectum eripiens oculis', 'snatching the view from (the) eyes', 'oculis' a dative of separation with a verb of taking away; the eyes are Hercules's, or anyone's. 'glomerat', 'gathers into a mass', 'rolls up', from 'glomus', 'a ball of thread'. 'sub antro', 'beneath the cave', within its hollow. 'fumiferam noctem', 'smoke-bearing night', a compound adjective in '-fer' (like 'pacifer' at 8.116) and a bold metaphor for black smoke. 'commixtis igne tenebris', ablative absolute or of description, 'with darkness mingled with fire', the flashes in the smoke. Elision 'prospect(um) eripiens'."""),
(258, 'atra.',
 "Did not bear it Alcides in his spirit, and himself through the fire\nwith headlong flung a leap, where most the billow\nthe smoke drives and with fog huge the cave seethes black.",
 "Alcides could not bear it in his fury; he flung himself with a headlong leap through the fire, where the smoke rolled its thickest billows and the huge cave seethed with black fog.",
 """'Non tulit… animis', 'did not bear (it) in his spirit', his pride would not allow it; 'animis' again a plural of high temper, as at 228. 'seque ipse', 'and himself, of his own act'. 'praecipiti… saltu', 'with a headlong leap', framing 'iecit'. 'qua', 'where', adverb. 'plurimus… fumus', 'smoke at its thickest', 'plurimus' used of something dense or massed. 'undam… agit', 'drives its wave', the smoke billowing like water. 'nebula… atra', 'with black fog', ablative of cause or means, framing 'ingens specus aestuat', 'the huge cave seethes', boils like a sea. Elisions 'sequ(e) ipse', 'nebulaqu(e) ingens'."""),
(261, 'guttur.',
 "Here Cacus in the darkness, fires useless spewing,\nhe seizes, in a knot embracing, and chokes, clinging,\nhis eyes squeezed out and his throat dry of blood.",
 "There in the darkness, as Cacus spewed his useless fires, he caught him, locked him in a wrestler's knot, and clung to him and throttled him, until the eyes started from his head and his throat was drained of blood.",
 """'Hic', 'here', inside the cave. 'incendia vana vomentem', 'spewing useless fires': the flames that had held others off do nothing to Hercules. 'corripit', 'snatches up', 'seizes'. 'in nodum complexus', 'embracing (him) into a knot', a wrestler's grip in which the limbs are locked round the opponent. 'angit inhaerens', 'chokes him, clinging close'. 'elisos oculos et siccum sanguine guttur', accusatives with 'angit', the participle and adjective proleptic: he chokes him so that the eyes are squeezed out and the throat is left bloodless; 'sanguine', ablative of separation with 'siccum', 'dry of blood'. The hero who strangled snakes in his cradle (289) and the Nemean lion kills by throttling again. Elision 'Cac(um) in'."""),
(265, 'protrahitur.',
 "Is laid open at once, its doors torn off, the house, black,\nand the dragged-off cows and the plunder sworn away\nto the sky are shown, and by the feet the shapeless carcass\nis dragged forth.",
 "At once the doors are wrenched away and the black house lies open; the stolen cattle and the plunder he had sworn he never took are shown to the light of day, and the shapeless carcass is dragged out by its feet.",
 """'Panditur', 'is thrown open', placed first. 'foribus… revolsis', ablative absolute, 'the doors torn away', 'revolsis' Greenough's spelling of 'revulsis' (from 'revello'). 'abstractae… boves', 'the cattle dragged away', feminine because most of them are cows. 'abiuratae… rapinae', 'the plunder sworn away': 'abiuro' is to deny on oath, so Cacus had sworn he had not taken it, as the infant Hermes swore to Apollo that he knew nothing of the cattle (Homeric Hymn to Hermes, from memory). 'caelo', dative, 'to the sky', the light of day that never reached the cave (8.195). 'informe cadaver', 'the shapeless corpse', a monster in death as in life. The long period ends with one emphatic word at the start of a line, 'protrahitur'. Elisions 'cael(o) ostenduntur', 'pedibusqu(e) informe'."""),
(267, 'ignis.',
 "Cannot be filled their hearts with gazing\nat the terrible eyes, the face and, shaggy with bristles,\nthe chest of the half-beast and the quenched in his throat fires.",
 "No one could gaze his fill at the dreadful eyes, the face, the chest of the half-beast rough with bristles, and the fires gone out in his throat.",
 """'Nequeunt expleri corda tuendo', 'hearts cannot be filled by gazing', no one can look long enough. 'tuendo', ablative of the gerund of 'tueor', 'by looking at', and it takes direct objects: 'terribilis oculos', 'the dreadful eyes' ('terribilis' accusative plural in '-is'), 'voltum', 'the face' (Greenough's 'voltum' for 'vultum', o after v again), 'pectora', 'the chest', and 'ignis', 'the fires'. 'villosa saetis', 'shaggy with bristles'. 'semiferi', genitive, 'of the half-wild one', 'half-beast', a word like 'semihominis' at 8.194. 'extinctos faucibus ignis', 'the fires put out in his throat', 'faucibus' ablative of place. Elisions 'semifer(i) atque', 'atqu(e) extinctos'."""),
(270, 'sacri.',
 "From that time has been celebrated the honour, and glad, the descendants\nhave kept the day, and first Potitius the founder\nand the house, of the Herculean guardian, Pinarian, rite.",
 "From that day the honour has been kept, and later generations have gladly observed the day; Potitius was the first to found it, and the house of the Pinarii guards the rite of Hercules.",
 """'Ex illo', 'from that (time)', 'tempore' understood. 'celebratus (est) honos', 'the honour has been paid', the verb 'est' left out; 'honos' is the older form of 'honor'. 'minores', 'the younger ones', descendants, later generations. 'servavere' = 'servaverunt'. 'primusque Potitius auctor', 'and Potitius (was) the first founder', again with the verb left out. The Potitii and Pinarii were two old families who held the cult of the Ara Maxima; in Livy's version (1.7, from memory) the Pinarii came late to the first feast and were made lesser ministers. The families kept the rite until 312 BC, when the censor Appius Claudius gave it to public slaves, and the Potitii died out within a year (Livy 9.29, from memory). 'domus… Pinaria', framing the line, 'custos', 'guardian', with 'Herculei… sacri', 'of the rite of Hercules'."""),
(272, 'semper.',
 "This altar in the grove he set up, which Greatest always\nwill be called by us, and will be, which Greatest always.",
 "He set up this altar in the grove, the altar that we shall always call the Greatest, and which will always be the greatest.",
 """'Hanc aram', 'this altar', the one beside which they are feasting (8.106). 'statuit', 'set up': the subject is most naturally Potitius, just named, though some took it of Hercules himself (from memory: Servius discusses the question). 'quae maxuma… dicetur… et erit quae maxuma', 'which will be called greatest and which will be greatest', the line echoing itself, name and fact made one. The Ara Maxima, the 'Greatest Altar' of Hercules, stood near the Forum Boarium. 'maxuma' is Greenough's spelling of 'maxima', the older '-umus' superlative, as with 'maxumus' at 8.136. 'nobis', dative of the agent with the passive, 'by us'. 'semper', 'always', ending both lines, the rite as lasting as Rome."""),
(275, 'volentes.”',
 "Therefore come, O young men, of such great in honour glories,\nbind with leaves your hair, and cups hold out in your right hands,\nand the common call god, and give wine willingly.”",
 "Come then, young men, in honour of deeds so glorious, wreathe your hair with leaves and lift the cups in your right hands; call on the god we share, and pour your wine with a good will.”",
 """Evander ends his speech, which closes here with Greenough's mark. 'Quare agite', 'come then', 'agite' an imperative used as an interjection. 'tantarum in munere laudum', 'in tribute to such great glories', 'munere' a service or offering, 'laudum' the deeds worth praising, the phrase framing 'in munere'. 'cingite fronde comas', 'bind your hair with leaves', the poplar of 276. 'porgite' = 'porrigite', 'hold out', an old syncopated form kept in poetry. 'dextris', 'in your right hands'. 'communem… deum', 'the god we share': Hercules, Greek by birth, is honoured by Arcadians and Trojans alike, and will be Rome's. 'date vina', 'give wine', pour a libation. 'volentes', 'willing', a word of ritual: the gods want worship gladly given. Elisions 'Quar(e) agite', 'agit(e) o', 'tantar(um) in', 'de(um) et'."""),
(278, 'scyphus.',
 "He had spoken, when the Herculean two-coloured poplar with its shade\nboth veiled his hair and, with leaves interwoven, hung,\nand the sacred filled his right hand cup.",
 "He had finished speaking when the two-coloured poplar, sacred to Hercules, shaded his hair, hanging there woven into a wreath of leaves, and the holy cup filled his right hand.",
 """'Dixerat… cum', 'he had spoken, when…', the inverted 'cum' clause: the main event comes in the 'cum' clause, with indicative verbs ('velavit… pependit… implevit'). The verb of speaking stands alone ('Dixerat'), as so often. 'Herculea… populus', 'the Herculean poplar': 'populus' with long first 'o' is the poplar, feminine, unlike 'populus', 'people'. The white poplar was sacred to Hercules; its leaves are dark above and pale below, hence 'bicolor'. Servius (from memory) says Hercules wreathed himself with it when he came up from the underworld. 'umbra', 'with its shade', in effect, the wreath's leaves round his head. 'sacer… scyphus', 'the sacred cup', framing the line: 'scyphus' is Greek, a two-handled cup, the vessel of Hercules in his rite. Elision 'foliisqu(e) innexa'."""),
(279, 'precantur.',
 "Swiftly all\non the table, glad, pour libation and the gods pray to.",
 "Quickly they all pour libations gladly on the table and pray to the gods.",
 """'Ocius', comparative of an adjective with no positive in use, here 'swiftly', 'at once', without a sense of comparison. 'in mensam… libant', 'pour libation onto the table': the feast is a sacred meal, and the table serves as an altar. 'laeti', 'glad', with the gladness Evander asked for in 'volentes' (275). 'divos' = 'deos', 'the gods'; 'divi' is the poets' word. 'precantur', 'they pray to', deponent with a direct object."""),
(282, 'ferebant.',
 "Sloping down meanwhile nearer becomes Vesper, Olympus,\nand now the priests and first Potitius were going,\nwith skins after the custom girded, and flames they were carrying.",
 "Meanwhile, as the sky sloped down, the evening star drew near, and now the priests were coming in procession, Potitius at their head, girt in skins as custom required, and carrying torches.",
 """A new paragraph in Greenough, and the narrative is Virgil's again. 'Devexo… Olympo', ablative absolute, 'heaven sloping down': 'Olympus', the gods' mountain, is often just 'the sky', and as the day wanes the heaven seems to slope westward. 'propior fit Vesper', 'Vesper becomes nearer', the evening star rises towards view. Elision 'Devex(o) interea'. 'sacerdotes primusque Potitius', two subjects with a plural verb, 'the priests, and first of them Potitius'. 'pellibus… cincti', 'girt with skins', a costume recalling Hercules's lion-skin. 'in morem', 'according to custom'. 'flammas', 'flames', torches for the night rite."""),
(284, 'aras.',
 "They renew the feast, and of the table welcome the second\ngifts they bring, and heap with loaded platters the altars.",
 "They renew the feast, bring the welcome gifts of the second course, and heap the altars with laden dishes.",
 """'Instaurant epulas', 'they renew the feast', start it afresh for the evening rite; 'instauro' is a ritual word for beginning again. 'mensae… secundae', 'of the second table', framing: the 'mensae secundae' were the course of fruit, nuts and sweets that ended a Roman dinner. 'grata… dona', 'welcome gifts', split over the line. 'cumulantque', 'and heap up'. 'oneratis lancibus', 'with laden platters', ablative of means: 'lanx' is a broad flat dish, used also for offerings. 'aras', the altars of the rite: the god shares the meal. Elision 'cumulantqu(e) oneratis'."""),
(287, 'senum;',
 "Then the Salii for the singing, the kindled altars round,\nwith poplar are present, bound about as to their temples, boughs,\nhere of young men a chorus, there of old men;",
 "Then the Salii stand ready to sing round the blazing altars, their temples bound with poplar boughs, one chorus of young men and one of old;",
 """The print has 'tum', lowercase after the full stop that ends 284, a misprint for 'Tum', corrected here; t keeps the print, because t must match the pinned source. The Salii, 'the leapers' (from 'salio'), were the dancing priests of Mars at Rome; Virgil gives them to Hercules, and Servius (from memory) says Hercules had Salii at Tibur. 'ad cantus', 'for the songs'. 'incensa altaria circum', 'round the kindled altars', the preposition after its noun (anastrophe). 'adsunt', 'are present' (Greenough's spelling of 'assunt'). 'populeis… ramis', 'with poplar boughs', framing. 'evincti tempora', 'bound as to the temples', the accusative of the part with a passive participle, the Greek use you have met before. 'hic… ille', 'this… that', 'one… the other'. Elisions 'Sali(i) ad', 'incens(a) altaria'."""),
(288, 'ferunt:',
 "who in song the praises\nHerculean and his deeds tell:",
 "and in their song they celebrate the glories and the deeds of Hercules:",
 """'qui', a connecting relative, 'and they'. 'carmine', 'in song'. 'laudes Herculeas et facta', 'the Herculean praises and deeds', i.e. the glorious deeds of Hercules worth praising; 'Herculeas' is the adjective from 'Hercules', as 'Herculea' at 276. 'ferunt', 'carry', 'tell', 'proclaim', a common sense of 'fero' with words of report. What follows is first a summary in indirect questions (288–293), 'how he… how he…', and then, at 293, the hymn itself in direct speech."""),
(289, 'angues,',
 "how the first of his stepmother\nmonsters with his hand, and twin squeezing he crushed snakes,",
 "how he gripped and crushed in his hands the first monsters his stepmother sent, the twin snakes,",
 """'ut', 'how', introducing indirect questions with the perfect subjunctive: 'eliserit… disiecerit… pertulerit'. 'prima novercae monstra', 'the first monsters of his stepmother': Juno, Jupiter's wife, hated Hercules, the son of Jupiter and Alcmena, and sent two serpents to kill him in his cradle; the baby strangled them, one in each hand (Pindar, Nemean 1, and Theocritus 24, from memory). 'geminosque… angues' explains 'monstra', the '-que' adding the detail, 'the monsters, that is, the twin snakes'. 'premens', 'squeezing'. 'eliserit', from 'elido', 'crushed out', as in 'elisos' at 261. The Latin Library's 'anguis' is only another accusative plural."""),
(293, 'pertulerit.',
 "how in war outstanding the same man overthrew cities,\nboth Troy and Oechalia, how hard a thousand labours\nunder king Eurystheus, by the decrees of Juno, unjust,\nhe endured.",
 "how he too laid low in war great cities, Troy and Oechalia, how he toiled through a thousand hard labours under king Eurystheus, by the will of unjust Juno.",
 """'idem', 'the same man', 'he also'. 'egregias… urbes', 'outstanding cities', framing. Troy: King Laomedon, Priam's father, cheated Hercules of the horses promised for saving his daughter Hesione, and Hercules sacked the city (told in Iliad 5, from memory); Virgil's Trojans hear of an earlier fall of Troy. Oechalia: Eurytus refused Hercules his daughter Iole, and Hercules destroyed his city (Sophocles, Trachiniae, from memory). 'mille', 'a thousand', of a great number. 'rege sub Eurystheo', 'under king Eurystheus', the king of Tiryns and Mycenae who set the labours; 'Eurystheo' scans with 'Eu' one syllable and '-eo' run together into one (synizesis). 'fatis Iunonis iniquae', 'by the decrees of hostile Juno'. Elisions 'bell(o) egregias', 'Troiamqu(e) Oechaliamque', 'Oechaliamqu(e) ut'."""),
(295, 'leonem.',
 "“You the cloud-born, unconquered, two-formed,\nHylaeus and Pholus, with your hand, you the Cretan slay\nmonster, and the vast under Nemea's rock lion.",
 "“You, unconquered one, slew with your own hand the cloud-born Centaurs, beings of two forms, Hylaeus and Pholus; you slew the monster of Crete and the huge lion beneath Nemea's crag.",
 """The hymn opens, in direct speech, marked by Greenough. 'Tu… tu', 'you… you', the repeated address of a hymn. 'nubigenas… bimembris', 'cloud-born… two-limbed' ('bimembris' accusative plural in '-is'): the Centaurs, half men and half horses, sons of Ixion and a cloud shaped like Juno. 'Hylaeeum', Greenough's spelling of the Greek 'Hylaeus'; Pholus was Hercules's Centaur host, who in the usual story died by accident when a poisoned arrow fell on his foot (from memory); Virgil makes both fall to the hero, as at Georgics 2.456–457 (from memory). 'invicte', vocative, 'unconquered', a cult title of Hercules. 'mactas', present, 'you slay', hymnic for deeds done. 'Cresia… prodigia', 'the Cretan monster', the bull, the seventh labour. 'Nemeae', genitive: the lion, the first labour. Elision 'prodigi(a) et'."""),
(297, 'cruento;',
 "You the Stygian trembled at, the lakes, you the doorkeeper of Orcus,\nbones upon lying in his cave half-eaten, bloody;",
 "Before you the Stygian lakes trembled, and the doorkeeper of Orcus, lying on half-gnawed bones in his bloody cave;",
 """'Te… te', the hymn's anaphora again, 'you' the object of 'tremuere' (= 'tremuerunt'), 'trembled at you', used transitively. 'Stygii… lacus', 'the Stygian lakes', the waters of the underworld, Styx among them. 'ianitor Orci', 'the doorkeeper of Orcus', Cerberus, the dog of the underworld; 'Orcus' is the god of death and so his realm. Fetching Cerberus to the upper world was the last of the labours. 'ossa super', 'upon bones', the preposition after its noun (anastrophe, as at 285). 'recubans', 'lying back'. 'semesa', 'half-eaten', from 'semi-' and 'esus'. 'antro… cruento', 'in his bloody cave', framing 'semesa'. No elisions."""),
(300, 'anguis.',
 "nor you any shapes, not frightened Typhoeus himself,\nlofty, weapons holding; not you of reason lacking\nthe Lernaean, with its throng of heads, stood round, snake.",
 "no shape of terror daunted you, not even Typhoeus himself, towering up with weapons in his hands; you did not lose your wits when the snake of Lerna surrounded you with its swarm of heads.",
 """'nec te ullae facies', 'nor (did) any shapes (frighten) you', 'terruit' serving both clauses. 'Typhoeus', three syllables, 'Ty-pho-eus', the Greek 'eu' one sound: the hundred-headed giant who made war on the gods. No labour pits Hercules against him; Virgil probably means the battle of gods and Giants, in which Hercules fought for Jupiter (from memory). 'arduus', 'towering'. 'rationis egentem', 'lacking reason', 'egeo' with the genitive: you kept your head. 'Lernaeus… anguis', 'the snake of Lerna', framing the line: the Hydra, whose heads grew again when cut off, the second labour. 'turba capitum', 'a crowd of heads', in apposition. 'circumstetit', 'stood around', the many heads ringing him. Elision 't(e) ullae'."""),
(302, 'secundo.”',
 "Hail, true of Jupiter offspring, glory added to the gods,\nand us and your rites, favouring, approach with foot propitious.”",
 "Hail, true son of Jupiter, glory added to the gods: come with favour to us and to your rites, and bless them with your coming.”",
 """The hymn ends with the traditional greeting and prayer, and Greenough closes the speech mark. 'Salve', 'hail', the word of address to a god. 'vera Iovis proles', 'true offspring of Jupiter', not of Amphitryon, the human father. 'decus addite divis', 'added to the gods as a glory': 'addite' is a vocative participle, 'you who have been added', since Hercules was raised to heaven after his death on Mount Oeta. 'et nos et tua… sacra', 'both us and your rites', the object of 'adi', 'approach', the imperative of 'adeo'. 'dexter', 'favourable', literally 'on the right', the lucky side. 'pede… secundo', 'with favouring foot', framing 'sacra', a ritual phrase for a god's gracious arrival, as at 10.255."""),
(304, 'ipsum.',
 "Such things in songs they celebrate; above all, Cacus's\ncave they add, and breathing with fires himself.",
 "Such were the themes of their songs; and to crown them all they add the cave of Cacus, and Cacus himself breathing fire.",
 """'Talia', 'such things', the content of the hymn, object of 'celebrant'. 'carminibus', 'in songs', ablative of means. 'super omnia', 'above all', 'on top of all of them', the climax of the hymn, the deed done here on this very ground. 'adiciunt', 'they add', from 'ad-' and 'iacio', the 'i' a consonant ('ad-yi-ci-unt'), so that 'ad' is long. 'spirantemque ignibus ipsum', 'and (Cacus) himself breathing with fires', 'ignibus' ablative. Elisions 'spelunc(am) adiciunt', 'spirantemqu(e) ignibus'."""),
(305, 'resultant.',
 "Resounds all the grove with the din, and the hills echo back.",
 "The whole grove rings with the noise, and the hills send back the echo.",
 """A single line to close the rite and the episode. 'Consonat', 'sounds together', 'resounds', placed first. 'omne nemus', 'the whole grove', the grove of the Ara Maxima (8.104, 271). 'strepitu', 'with the din', ablative of cause. 'resultant', 'leap back', 'echo', a frequentative of 'resilio' ('re-' + 'salio'): the hills of the future Rome, the Palatine and the Aventine, give back the sound of the Salii, whose name too comes from 'salio'. No elisions."""),
]

P = A.part('aeneid-059'); L = A.lines_of(P); paras = {l['n'] for l in L if l['p']}
cuts = A.cut(P, [(u[0], u[1]) for u in U])
sents = []; prev_end_line = None
for (t, ln), (_, _t, l, i, n) in zip(cuts, U):
    u = {'t': t, 'l': l, 'i': i, 'n': n}
    if prev_end_line != ln and ln in paras: u['p'] = True
    u['v'] = True; u['ln'] = ln; sents.append(u)
    prev_end_line = ln + t.count('\n')
    if t.count('\n') != l.count('\n'): print('LINE COUNT', ln, repr(t[:30]), t.count('\n'), l.count('\n'))
    if t.count('\n') > 4: print('TOO LONG', ln)
    if '\n' in i: print('NEWLINE IN i', ln)
A.jdump({'title': TITLE, 'titleEn': TITLE_EN, 'part': PART, 'about': ABOUT, 'sentences': sents}, os.path.join(HERE, 'units.json'))
print(len(sents), 'units')
